  }

PATCH /users/124
  Request body (only fields to update):
  { "name": "Robert" }
  Response 200:
  { "id": 124, "name": "Robert", "email": "bob@example.com", ... }

ERROR RESPONSE (consistent shape matters):
  {
    "error": {
      "code": "VALIDATION_ERROR",
      "message": "Email is required",
      "details": [
        { "field": "email", "message": "Email is required" }
      ]
    }
  }
